function HasCloseElements(numbers : array of real; threshold : real): boolean;
begin
  Result := False;
  for var i := 0 to numbers.Length - 2 do
    for var j := i + 1 to numbers.Length - 1 do
      if abs(numbers[i] - numbers[j]) < threshold then
      begin
        Result := True;
        exit;
      end;
end;


function SeparateParenGroups(parenString : string): array of string;
begin
  var stack := new Stack<char>;
  var result := new List<string>;
  var sb := new StringBuilder;
  var i := 0;
  while i < parenString.Length do
  begin
    if parenString[i] = ' ' then
    begin
      i += 1;
      continue;
    end;
    if parenString[i] = '(' then
    begin
      stack.Push(parenString[i]);
      sb.Append(parenString[i]);
    end
    else
    begin
      sb.Append(parenString[i]);
      if stack.Count = 0 then
        result.Add(sb.ToString)
      else
      begin
        var lastOpenBrace := stack.Pop();
        if lastOpenBrace = '(' then
          sb.Clear;
        sb.Append(parenString[i]);
      end;
    end;
    i += 1;
  end;
  Result := result.ToArray;
end;


