    Result[i] := numbers[j];
    i += 1;
    Result[i] := delimeter;
    i += 1;
  end;
  Result[^1] := numbers[^1];
end;


function ParseNestedParens(parenString: string): array of integer;
begin
  var maxLevel := -1;
  var currentLevel := 0;
  var result := new integer[parenString.Length];
  for var i := 0 to parenString.Length - 1 do
  begin
    if parenString[i] = '(' then
    begin
      currentLevel += 1;
      if currentLevel > maxLevel then
        maxLevel := currentLevel;
    end
    else if parenString[i] = ')' then
    begin
      currentLevel -= 1;
    end;
    result[i] := maxLevel;
  end;
  Result := result;
end;


