function RollingMax(numbers : array of integer): array of integer;  { From a given list of integers, generate a list of rolling maximum element found until given moment
    in the sequence.
    >>> RollingMax([1, 2, 3, 2, 3, 4, 2])
    [1, 2, 3, 3, 3, 4, 4] }

begin
  Result := new integer[numbers.Length];
  var max := numbers[0];
  Result[0] := max;
  for var i := 1 to numbers.Length - 1 do
  begin
    if numbers[i] > max then
      max := numbers[i]
    Result[i] := max;
  end;
end;

