function MakePalindrome(str: string): string;
begin
  var i := str.Length - 1;
  while i >= 0 do
  begin
    if IsPalindrome(str.Substring(0, i + 1)) then
    begin
      Result := str + ReverseString(str.Substring(0, i + 1));
      exit;
    end;
    i := i - 1;
  end;
end;


