function FindClosestElements(numbers : array of real): (real, real);
begin
  var (min1, min2) := (numbers[0], numbers[1]);
  for var i := 0 to numbers.Length - 2 do
  begin
    if abs(numbers[i] - numbers[i + 1]) < abs(min1 - min2) then
    begin
      (min1, min2) := (numbers[i], numbers[i + 1]);
    end
    else if abs(numbers[i] - numbers[i + 1]) = abs(min1 - min2) then
    begin
      if numbers[i] < min1 then
        (min1, min2) := (numbers[i], min1);
      if numbers[i + 1] < min2 then
        (min1, min2) := (min1, numbers[i + 1]);
    end;
  end;
  Result := (min1, min2)
end;


