function Factorize(n: integer): array of integer;
begin
  Result := new integer[n];
  var i := 0;
  while n mod 2 = 0 do
  begin
    Result[i] := 2;
    n := n div 2;
    i += 1;
  end;
  var sqrtn := Sqrt(n);
  for var d := 3 to sqrtn do
  while n mod d = 0 do
  begin
    Result[i] := d;
    n := n div d;
    i += 1;
  end;
  if n > 1 then
  begin
    Result[i] := n;
    i += 1;
  end;
  SetLength(Result, i)
end;


