function Median(l : array of integer): real;
begin
  var n := l.Length;
  if n = 0 then
    raise new System.ArgumentException('List is empty');
  if n = 1 then
    Result := l[0]
  else
  begin
    var s := new System.Collections.SortedList(l);
    var m := s.Count div 2;
    if s.Count mod 2 = 0 then
      Result := (s[m] + s[m + 1]) / 2
    else
      Result := s[m + 1];
  end;
end;


