function Monotonic(l : array of integer): boolean;
begin
  var i := 1;
  while i < l.Length do
  begin
    if l[i] = l[i - 1] then
      i += 1;
    else
      break;
  end;
  if i = 1 then
    Result := True
  else
  begin
    var sign := l[1] - l[0];
    for var j := 2 to i - 1 do
    begin
      if (l[j] - l[j - 1]) * sign < 0 then
        Result := False
      else
        sign := l[j] - l[j - 1];
    end;
    Result := True;
  end;
end;


