function CircularShift(x : integer; shift : integer): string;  {Circular shift the digits of the integer x, shift the digits right by shift
    and return the _result as a string.
    If shift > number of digits, return digits reversed.
    >>> CircularShift(12, 1)
    "21"
    >>> CircularShift(12, 2)
    "12" }
begin
  var s := x.ToString;
  var n := s.Length;
  var res := new string(n);
  for var i := 0 to n - 1 do
  begin
    res[i] := s[(i + shift) mod n];
  end;
  Result := res;
end;


