function Pluck(arr: array of integer): array of integer;
begin
  var smallest_value := integer.MaxValue;
  var smallest_index := integer.MaxValue;
  for var i := 0 to arr.Length - 1 do
  begin
    if (arr[i] < smallest_value) and (arr[i] mod 2 = 0) then
    begin
      smallest_value := arr[i];
      smallest_index := i;
    end;
  end;
  if smallest_value = integer.MaxValue then
    Result := []
  else
    Result := [smallest_value, smallest_index];
end;


function Search(lst: array of integer): integer;
begin
  var d := new Dictionary<integer, integer>;
  foreach var i in lst do
  begin
    if d.ContainsKey(i) then
      d[i] += 1
    else
      d.Add(i, 1);
  end;
  var max := -1;
  var maxFreq := -1;
  foreach var kvp in d do
  begin
    if kvp.Value > maxFreq then
    begin
      max := kvp.Key;
      maxFreq := kvp.Value;
    end;
  end;
  Result := max;
end;


function StrangeSortList(lst: array of integer): array of integer;
begin
  Result := lst.Clone;
  var n := Result.Length;
  var i := 0;
  while i < n do
  begin
    var min := Result[i];
    var max := Result[i];
    for var j := i to n - 1 do
    begin
      if Result[j] < min then
        min := Result[j];
      if Result[j] > max then
        max := Result[j];
    end;
    Result[i] := max;
    Result[i + 1] := min;
    i += 2;
  end;
end;


function TriangleArea(a, b, c: real): real;
begin
  if (a + b > c) and (a + c > b) and (b + c > a) then
    Result := Sqrt(4 * a * a * b * b - a * a * Sqr(c) - b * b * Sqr(c) - c * c * Sqr(a) - 2 * c * c * b * b) / 4
  else
    Result := -1;
end;


