function SmallestChange(arr: array of integer): integer;
begin
  var n := arr.Length;
  var i := 0;
  var j := n - 1;
  var changes := 0;
  while i < j do
  begin
    if arr[i] <> arr[j] then
    begin
      changes += 1;
      if arr[i] <> arr[i + 1] then
        i += 1
      else
        j -= 1;
    end
    else
    begin
      i += 1;
      j -= 1;
    end;
  end;
  Result := changes;
end;


