function Encrypt(s: string): string;
begin
  var sb := new StringBuilder(s.Length);
  foreach var c in s do
  begin
    if c.IsLetter then
    begin
      var cc := char.ToLower(c);
      if cc >= 'a' and cc <= 'z' then
        sb.Append(char.ToLower((char)(cc - 2 + 26)));
      if cc >= 'A' and cc <= 'Z' then
        sb.Append(char.ToUpper((char)(cc - 2 + 26)));
    end
    else sb.Append(c);
  end;
  Result := sb.ToString;
end;


