function MoveOneBall(arr: array of integer): boolean;
begin
  if arr.Length = 0 then
    exit(True);
  var i := arr.Length - 1;
  while (i > 0) and (arr[i] < arr[i - 1]) do
  begin
    i -= 1;
  end;
  if i = 0 then
    exit(True);
  var j := i - 1;
  while (j >= 0) and (arr[j] > arr[j + 1]) do
  begin
    j -= 1;
  end;
  if j < 0 then
    exit(True);
  var k := j + 1;
  while (k < arr.Length) and (arr[k] < arr[j]) do
  begin
    k += 1;
  end;
  if k = arr.Length then
    exit(True);
  exit(False);
end;


function Exchange(lst1, lst2: array of integer): string;
