  for var i := 0 to lst1.Count - 1 do
  begin
    if lst1[i] mod 2 = 1 then
    begin
      var j := lst2.IndexOf(lst1[i]);
      if j = -1 then
        continue;
      lst2[j] := lst1[i];
      lst1[i] := 0;
      cnt := cnt - 1;
    end;
  end;
  Result := cnt = 0 ? 'YES' : 'NO';
end;


