function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var n := grid.Length;
  var m := grid[0].Length;
  var res := 0;
  var buckets := new integer[n, m];
  for var i := 0 to n - 1 do
    for var j := 0 to m - 1 do
      if grid[i, j] = 1 then
        buckets[i, j] := capacity;
  for var i := 0 to n - 1 do
    for var j := 0 to m - 1 do
      if buckets[i, j] > 0 then
      begin
        var cnt := 0;
        while buckets[i, j] > 0 do
        begin
          buckets[i, j] -= 1;
          cnt += 1;
          if j + 1 < m then
            buckets[i, j + 1] -= 1;
          j += 1;
        end;
        res += cnt;
      end;
  Result := res;
end;


