function ValidDate(date: string): boolean;
begin
  var parts := date.Split('-');
  if (parts.Length <> 3) or (parts[0].Length <> 2) or (parts[1].Length <> 2) or (parts[2].Length <> 4) then
    Result := False
  else
  begin
    var month := Convert.ToInt32(parts[0]);
    var day := Convert.ToInt32(parts[1]);
    var year := Convert.ToInt32(parts[2]);
    if (month < 1) or (month > 12) or (day < 1) or (day > 31) or (year < 1) or (year > 9999) then
      Result := False
    else
    begin
      if month = 2 then
        if day > 29 then
          Result := False
        else
          Result := True
      else if month = 4 then
        if day > 30 then
          Result := False
        else
          Result := True
      else if month = 6 then
        if day > 30 then
          Result := False
        else
          Result := True
      else if month = 9 then
        if day > 30 then
          Result := False
        else
          Result := True
      else
        Result := True
    end
  end
end;


