function Intersection(interval1, interval2 : array of integer): string;
begin
  var (start1, end1), (start2, end2) := (interval1[0], interval1[1]), (interval2[0], interval2[1]);
  if end1 < start2 or end2 < start1 then
    Result := 'NO'
  else if end1 = start2 then
    Result := 'YES'
  else if end1 - start1 = end2 - start2 then
    Result := 'YES'
  else Result := 'NO';
end;


