function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var res := new List<integer>(n);
  var dp := new integer[n, n];
  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      dp[i, j] := grid[i, j];
  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      for var x := 0 to n - 1 do
        for var y := 0 to n - 1 do
          if (i, j) <> (x, y) then
            dp[i, j] := min(dp[i, j], dp[x, y] + grid[i, j]);
  var min := dp[0, 0];
  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      if dp[i, j] < min then
        min := dp[i, j];
  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      if dp[i, j] = min then
        res.Add(grid[i, j]);
  res.Sort;
  Result := res.ToArray;
end;


function Tri(n: integer): array of real;
begin
  Result := new real[n + 1];
  Result[0] := 3;
  for var i := 1 to n do
  begin
    if i mod 2 = 0 then
      Result[i] := Result[i - 1] + Result[i - 2] + Result[i - 1]
    else
      Result[i] := Result[i - 1] + Result[i - 2] + Result[i + 1];
  end;
end;


function Digits(n : integer): integer;
begin
  var odd := False;
  var product := 1;
  while n > 0 do
  begin
    var digit := n mod 10;
    if digit mod 2 = 1 then
      odd := True;
    if odd then
      product *= digit;
    n := n div 10;
  end;
  Result := product;
end;


