function SumSquares(lst: array of real): integer;
begin
  var sum := 0;
  for var i := 0 to lst.Length - 1 do
    sum += Round(lst[i]) * Round(lst[i]);
  Result := sum;
end;


function CheckIfLastCharIsALetter(txt: string): boolean;
begin
  var lastChar := txt.LastOrDefault;
  Result := (lastChar >= 'a' && lastChar <= 'z') || (lastChar >= 'A' && lastChar <= 'Z');
end;


function CanArrange(arr: array of integer): integer;
begin
  var n := arr.Length;
  var i := n - 1;
  while (i > 0) and (arr[i] <= arr[i - 1]) do
    i -= 1;
  if i = 0 then
    Result := -1
  else
  begin
    var j := i - 1;
    while (j >= 0) and (arr[j] <= arr[i - 1]) do
      j -= 1;
    Result := j + 1;
  end;
end;


function LargestSmallestIntegers(lst : array of integer): (integer, integer);
begin
  var max_neg := integer.MinValue;
  var min_pos := integer.MaxValue;
  foreach var i in lst do
  begin
    if i < 0 then
      max_neg := max(max_neg, i);
    if i > 0 then
      min_pos := min(min_pos, i);
  end;
  Result := (max_neg, min_pos);
end;


function CompareOne(a, b : object): object;
begin
  if a is integer then
    Result := integer(a)
  else if a is real then
    Result := real(a)
  else if a is string then
  begin
    var a_str := a.ToString;
    if a_str.Contains(',') then
      Result := real(a_str)
    else if a_str.Contains('.') then
      Result := real(a_str)
    else Result := integer(a)
  end
  else if b is integer then
    Result := integer(b)
  else if b is real then
    Result := real(b)
  else if b is string then
  begin
    var b_str := b.ToString;
    if b_str.Contains(',') then
      Result := real(b_str)
    else if b_str.Contains('.') then
      Result := real(b_str)
    else Result := integer(b)
  end
  else if a = b then
    Result := nil
  else Result := a
end;


function IsEqualToSumEven(n: integer): boolean;
begin
  Result := False;
  if n mod 2 = 0 then
  begin
    var i := 2;
    while i * i <= n do
    begin
      if n mod i = 0 then
      begin
        var j := i;
        while n mod j = 0 do
        begin
          j += 2;
        end;
        if j * j = n then
          Result := True;
      end;
      i += 1;
    end;
  end;
end;


function SpecialFactorial(n: integer): integer;
begin
  Result := 1;
  for var i := 1 to n do
    Result *= i;
end;


function FixSpaces(text: string): string;
begin
  var sb := new StringBuilder(text);
  var i := 0;
  while i < sb.Length do
  begin
    if sb[i] = ' ' then
    begin
      sb[i] = '_';
      if i + 1 < sb.Length and sb[i + 1] = ' ' then
        sb[i + 1] = '-'
    end;
    i += 1;
  end;
  Result := sb.ToString;
end;


