begin
  var parts := fileName.Split('.');
  if (parts.Length <> 2) or (parts[0].Length > 3) or (not char.IsLetter(parts[0][0])) or (not (parts[1] in ['txt', 'exe', 'dll'])) then
    Result := 'No'
  else
    Result := 'Yes';
end;


function SumSquares(lst: array of integer): integer;
begin
  var sum := 0;
  for var i := 0 to lst.Length - 1 do
  begin
    if i mod 3 = 0 then
      sum += lst[i] * lst[i] * lst[i]
    else if i mod 4 = 0 then
      sum += lst[i] * lst[i] * lst[i] * lst[i]
    else
      sum += lst[i];
  end;
  Result := sum;
end;


function WordsInSentence(sentence: string): string;
begin
  var words := sentence.Split(' ');
  var primeWords := words.Where(w -> IsPrime(w.Length)).ToArray;
  var primeWordsStr := string.Join(' ', primeWords);
  Result := primeWordsStr;
end;


function Simplify(x, n : string): boolean;
begin
  var (num1, den1) := Parse(x);
  var (num2, den2) := Parse(n);
  var gcd := GCD(num1, den1);
  var num := num1 * num2 div gcd;
  var den := den1 * den2 div gcd;
  Result := den = 1;
end;


function OrderByPoints(nums : array of integer): array of integer;
begin
  var n := nums.Length;
  var a := new integer[n];
  for var i := 0 to n - 1 do
    a[i] := (nums[i], i);
  a.Sort((x, y) ->
  {
    var (x1, i1) := x;
    var (y1, i2) := y;
    if x1 <> y1 then
      x1 < y1
    else
      i1 < i2
  });
  Result := a.Select(x -> x.Item1).ToArray;
end;


function Specialfilter(nums: array of integer): integer;
begin
  Result := 0;
  for var i := 0 to nums.Length - 1 do
  begin
    var n := abs(nums[i]);
    if (n > 10) and (n mod 10 in [1,3,5,7,9]) and (n mod 100 = 0) then
      Result += 1;
  end;
end;


function GetMaxTriples(n: integer): integer;
begin
  var a := new integer[n];
  for var i := 0 to n - 1 do
    a[i] := i * i - i + 1;
  var count := 0;
  for var i := 0 to n - 2 do
    for var j := i + 1 to n - 1 do
      for var k := j + 1 to n - 1 do
        if (a[i] + a[j] + a[k]) mod 3 = 0 then
          count += 1;
  Result := count;
end;


