end;


function DoubleTheDifference(lst : array of real): integer;
begin
  var sum := 0;
  foreach var x in lst do
  begin
    if x < 0 then continue;
    if not integer(x) then continue;
    if integer(x) mod 2 <> 0 then continue;
    sum += integer(x) * integer(x);
  end;
  Result := sum;
end;


