function StrongestExtension(className: string; extensions: array of string): string;
begin
  var max := -1.0;
  var maxExt := '';
  foreach var ext in extensions do
  begin
    var cap := ext.Count(c -> Char.IsUpper(c));
    var sm := ext.Count(c -> Char.IsLower(c));
    var strength := cap - sm;
    if strength > max then
    begin
      max := strength;
      maxExt := ext;
    end;
  end;
  Result := className + '.' + maxExt;
end;


function CycpatternCheck(a, b: string): boolean;
begin
  var n := a.Length;
  for var i := 0 to n - 1 do
  begin
    var s := a.Substring(i, n);
    if s.Contains(b) or s.Contains(b.Reverse) then
      exit(True);
  end;
  Result := False;
end;


function EvenOddCount(num : integer): (integer, integer);
begin
  var n := abs(num);
  var even := 0;
  var odd := 0;
  while n > 0 do
  begin
    var digit := n mod 10;
    if digit mod 2 = 0 then
      even += 1
    else
      odd += 1;
    n := n div 10;
  end;
  Result := (even, odd);
end;


function IntToMiniRoman(number: integer): string;
begin
  var roman := '';
  var values := new List<int>(new int[] {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1});
  var numerals := new List<string>(new string[] {'m', 'cm', 'd', 'cd', 'c', 'xc', 'l', 'xl', 'x', 'ix', 'v', 'iv', 'i'});
  for var i := 0 to values.Count - 1 do
  begin
    while number >= values[i] do
    begin
      number -= values[i];
      roman += numerals[i];
    end;
  end;
  Result := roman;
end;


function RightAngleTriangle(a, b, c : integer): boolean;
begin
  Result := (a*a + b*b = c*c) or (b*b + c*c = a*a) or (c*c + a*a = b*b);
end;


function FindMax(words : array of string): string;
begin
  var max := -1;
  var maxWord := '';
  foreach var word in words do
  begin
    var uniqueCount := word.Distinct.Count;
    if uniqueCount > max then
    begin
      max := uniqueCount;
      maxWord := word;
    end
    else if uniqueCount = max then
    begin
      if word < maxWord then
        maxWord := word;
    end;
  end;
  Result := maxWord;
end;


function Eat(number, need, remaining : integer): (integer, integer);
begin
  if need <= remaining then
  begin
    Result := (number + need, remaining - need);
  end
  else
  begin
    Result := (number + remaining, 0);
  end;
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 0 to op.Length - 1 do
  begin
    case op[i] of
      '+': res += operand[i + 1];
      '-': res -= operand[i + 1];
      '*': res *= operand[i + 1];
      '//': res := res div operand[i + 1];
      '**': res := Power(res, operand[i + 1]);
    end;
  end;
  Result := res;
end;


function Solve(s: string): string;
begin
  var sb := new StringBuilder(s);
  for var i := 0 to sb.Length - 1 do
  begin
    if sb[i].IsLetter then
    begin
      if sb[i].IsLower then
        sb[i] := sb[i].ToUpper
      else
        sb[i] := sb[i].ToLower;
    end
    else
      sb[i] := sb[i];
  end;
  if sb.Length = 0 then
    sb.Reverse;
  Result := sb.ToString;
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
    Result := nil
  else
    Result := System.Security.Cryptography.MD5.Create().ComputeHash(Encoding.UTF8.GetBytes(text)).Aggregate(new StringBuilder, (s, b) -> s.Append(b.ToString('x2'))).ToString;
end;


function GenerateIntegers(a, b : integer): array of integer;
begin
  var res := new List<integer>;
  for var i := a to b do
    if i mod 2 = 0 then
      res.Add(i);
  res.Sort;
  Result := res.ToArray;
end;
